===== AssignHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns a shared {@code householdId} when the request opted in with {@code sharesHousehold: true}
 * and another owner already shares the same last name and address. The new owner and every existing
 * household member receive the same stable identifier (see {@link OwnerHousehold#id}), so joiners
 * converge on one value. Runs after {@link BuildOwner}, so the built owner is available to stamp.
 * When nobody else is in the household there is no one to share with, so the id is left null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        boolean hasHousehold = false;
        String householdId = OwnerHousehold.id(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.sameHousehold(request.getLastName(), request.getAddress(),
                    existing.getLastName(), existing.getAddress())) {
                hasHousehold = true;
                // Back-fill members that predate the household so every member shares the id.
                if (existing.getHouseholdId() == null) {
                    existing.setHouseholdId(householdId);
                    ownerRepository.save(existing);
                }
            }
        }
        if (hasHousehold) {
            owner.setHouseholdId(householdId);
        }
    }
}
===== AssignHouseholdSize.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the {@code householdSize} to a newly built owner: the number of owners that share the
 * same {@code householdId} once this owner is included. Runs after {@link AssignHousehold} (which
 * stamps and back-fills the household id) and before the owner is saved, so the count reflects the
 * household as it stands after this create. When the owner joined no household ({@code householdId}
 * is null) the household is just this owner, so the size is 1.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            owner.setHouseholdSize(1);
            return;
        }
        int count = 1; // the owner being created is not yet persisted
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}
===== CheckOwnerIdentityUnique.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
import org.springframework.samples.petclinic.util.OwnerIdentity;

/**
 * The single duplicate-detection step for the create-owner pipeline: it rejects a request whose
 * derived {@code identityKey} (normalizedTelephone|email|householdId) exactly equals an existing
 * owner's. This one check subsumes the former separate telephone, email and household checks.
 *
 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold}, so the new owner's telephone and
 * email are normalized and its household id is finalized (including any back-fill of existing
 * members) - the key is therefore compared against every other owner's finalized key. Because the
 * telephone is part of the key, two household members with different telephones have different keys
 * and both are allowed; only an exact whole-key match is a duplicate. Throws
 * {@link DuplicateIdentityException} (handled as 409) on a collision.
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = OwnerIdentity.key(owner);
        for (Owner existing : ownerRepository.findAll()) {
            // The owner being created is not yet persisted, so findAll() returns only other owners.
            if (identityKey.equals(OwnerIdentity.key(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
