===== OwnerIdentity =====
package org.springframework.samples.petclinic.util;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey} - the single value all duplicate detection is expressed
 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)},
 * where the telephone is the owner's stored E.164 form and the email is its stored lower-cased form.
 * Two owners are duplicates when, and only when, their whole identity keys are equal; because the
 * telephone is part of the key, household members with different telephones have different keys.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * @param owner the owner whose identity key to derive.
     * @return the identity key {@code telephone|email|householdId}, with a missing email or
     *         householdId contributing an empty segment.
     */
    public static String key(Owner owner) {
        return segment(owner.getTelephone()) + "|" + segment(owner.getEmail()) + "|"
                + segment(owner.getHouseholdId());
    }

    private static String segment(String value) {
        return value == null ? "" : value;
    }
}
===== DuplicateIdentityException =====
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request derives an {@code identityKey} - the consolidated
 * {@code normalizedTelephone|email|householdId} value - that exactly equals an existing owner's.
 * This one key expresses what used to be the separate telephone, email and household duplicate
 * checks. Handled globally by {@link DuplicateIdentityExceptionHandler}, which responds 409.
 */
public class DuplicateIdentityException extends Exception {

    private final String identityKey;

    public DuplicateIdentityException(String identityKey) {
        super("Owner identity already in use: " + identityKey);
        this.identityKey = identityKey;
    }

    public String getIdentityKey() {
        return this.identityKey;
    }
}
===== OwnerHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.regex.Pattern;

/**
 * Shared household rules for the create-owner pipeline. Two owners belong to the same household
 * when their last name and address match after normalization (case-insensitive, with runs of
 * whitespace collapsed to a single space and leading/trailing whitespace trimmed). The household
 * identifier is a stable value derived from that same normalized last name and address, so every
 * owner in a household resolves to the same id without coordination.
 */
final class OwnerHousehold {

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private OwnerHousehold() {
    }

    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase();
    }

    static boolean sameHousehold(String lastNameA, String addressA, String lastNameB, String addressB) {
        return normalize(lastNameA).equals(normalize(lastNameB))
                && OwnerAddress.normalize(addressA).equals(OwnerAddress.normalize(addressB));
    }

    /** Stable identifier for the household of the given last name and address. */
    static String id(String lastName, String address) {
        String key = normalize(lastName) + "�" + OwnerAddress.normalize(address);
        return "HH-" + sha256hex(key).substring(0, 12).toUpperCase();
    }

    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }
}

